
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_m06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_m06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.095024525884354e+00, -3.011267211746044e+00, -2.895138059239525e+00, -2.741316398600290e+00, -2.555470070296159e+00, -2.365255327706436e+00, -2.195713878489585e+00, -1.949042854627804e+00, -1.541599598181845e+00, -1.222409351183970e+00, -7.744671702617074e-01, -4.772035446039255e-01, -4.466566397673379e-01, -3.696412034269947e-01, -2.713182315071913e-01, -1.890012947566283e-01, -1.632112805779310e-01, -1.131196550651732e-01, -2.746535498596593e-02, -3.106333058101832e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


